"""Migration of the Meridian CRM 4.2 nightly case escalation job."""

from datetime import datetime


def _datediff(today: str, open_date: str) -> int:
    """Return whole calendar days today minus open_date under legacy semantics."""
    if not today or not open_date or today == "00000000" or open_date == "00000000":
        return 0

    today_date = datetime.strptime(today, "%Y%m%d").date()
    open_date_value = datetime.strptime(open_date, "%Y%m%d").date()
    return (today_date - open_date_value).days


def escalate(cases: list[dict], today: str) -> list[dict]:
    """Return auto-escalation workflow events for overdue live cases."""
    events: list[dict] = []

    for case in sorted(cases, key=lambda row: str(row["CASE_ID"])):
        if case.get("DEL_FLG", "") == "Y":
            continue

        status = case.get("STAT_CD", "")
        days_open = _datediff(today, case.get("OPEN_DT", ""))

        if status == "N" and days_open >= 2:
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case["CASE_ID"]),
                    "event": "auto_escalate",
                }
            )
        elif (
            status == "A"
            and case.get("ESC_FLG", "") != "Y"
            and days_open >= 7
        ):
            events.append(
                {
                    "workflow": "case_lifecycle",
                    "entity_id": str(case["CASE_ID"]),
                    "event": "auto_escalate",
                }
            )

    return events
